create function storage.foldername(text) returns text[] language sql immutable as $$select (string_to_array($1,'/'))[1:array_length(string_to_array($1,'/'),1)-1]$$;
create function storage.allow_any_operation(text[]) returns boolean language sql stable as $$select coalesce(nullif(current_setting('crm.test_storage_operation',true),''),'object.list')=any($1)$$;
