CREATE OR REPLACE FUNCTION public.crm_record_presentation_open(target_token uuid, event_nonce uuid, consented boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare sid bigint;begin
if not coalesce(consented,false) then return false;end if;sid:=crm_private.valid_share(target_token);if sid is null then return false;end if;
if (select count(*) from public.marketing_share_events where share_id=sid)>10000 then return false;end if;
insert into public.marketing_share_events(share_id,nonce) values(sid,event_nonce) on conflict(share_id,nonce) do nothing;return true;end $function$
;
CREATE OR REPLACE FUNCTION crm_private.public_asset(path text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select exists(select 1 from public.marketing_assets a join public.asset_versions v on v.id=a.current_version_id join public.asset_relations r on r.asset_id=a.id join public.properties p on p.id=r.property_id or exists(select 1 from public.development_units u where u.property_id=p.id and u.development_id=r.development_id) where v.storage_path=path and a.status='aprovado' and a.visibility='public' and(a.expires_at is null or a.expires_at>now()) and p.deleted_at is null and p.publish_on_site and p.presentation_enabled and p.workflow_status in ('aprovado','publicado') and p.status in ('ativo','reservado','vendido','alugado')) $function$
;
CREATE OR REPLACE FUNCTION crm_private.guard_share()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ declare pid bigint;aid bigint; begin
if tg_op='UPDATE' then if (to_jsonb(new)-'revoked_at')<>(to_jsonb(old)-'revoked_at') or old.revoked_at is not null or new.revoked_at is null then raise exception using errcode='42501',message='Links são imutáveis. Revogue e gere um novo link.';end if;return new;end if;
if new.expires_at<=now() or new.expires_at>now()+interval '90 days' then raise exception using errcode='23514',message='Validade deve ficar entre agora e 90 dias.';end if;
if new.lead_id is not null and not exists(select 1 from public.leads l where l.id=new.lead_id) then raise exception using errcode='42501',message='Lead não autorizado.';end if;
if new.client_id is not null and not exists(select 1 from public.clients c where c.id=new.client_id and c.deleted_at is null) then raise exception using errcode='42501',message='Cliente não autorizado.';end if;
if new.collection_id is not null and not exists(select 1 from public.marketing_collections c where c.id=new.collection_id) then raise exception using errcode='42501',message='Coleção não autorizada.';end if;
foreach pid in array new.property_ids loop if not exists(select 1 from public.properties p where p.id=pid and p.deleted_at is null and p.publish_on_site and p.presentation_enabled and p.workflow_status in ('aprovado','publicado') and p.status in ('ativo','reservado','vendido','alugado')) then raise exception using errcode='42501',message='Imóvel sem apresentação pública autorizada.';end if;end loop;
foreach aid in array new.asset_ids loop if not exists(select 1 from public.marketing_assets a join public.asset_versions v on v.id=a.current_version_id where a.id=aid and a.status='aprovado' and a.visibility='public' and(a.expires_at is null or a.expires_at>now()) and exists(select 1 from public.asset_relations r where r.asset_id=a.id and(r.property_id=any(new.property_ids) or exists(select 1 from public.development_units u where u.development_id=r.development_id and u.property_id=any(new.property_ids))))) then raise exception using errcode='42501',message='Material sem aprovação ou vínculo autorizado.';end if;end loop;
return new;end $function$
;
CREATE OR REPLACE FUNCTION crm_private.share_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
if new.lead_id is not null then insert into public.lead_activities(lead_id,user_id,type,description) values(new.lead_id,new.owner_id,'note','Apresentação gerada: '||new.title||' · canal '||new.channel||' · link '||new.token::text); end if;
insert into public.crm_event_log(owner_id,event_type,entity_id,idempotency_key) values(new.owner_id,'presentation_created',new.id,'share:'||new.id);
if new.lead_id is not null and exists(select 1 from public.crm_automation_preferences where owner_id=new.owner_id and share_followup) then insert into public.tasks(title,broker_id,lead_id,property_id,due_at) select 'Retornar sobre apresentação: '||new.title,new.owner_id,new.lead_id,new.property_ids[1],now()+make_interval(days=>p.followup_days) from public.crm_automation_preferences p where p.owner_id=new.owner_id;end if;return new;end $function$
;
