CREATE OR REPLACE FUNCTION public.protect_lead_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if new.origin_type is distinct from old.origin_type then
    raise exception 'A origem pessoal/institucional do lead e permanente.' using errcode = '42501';
  end if;
  if auth.uid() is not null and not public.can_manage_operations() and
    (new.broker_id is distinct from old.broker_id or new.source is distinct from old.source or new.origin_type is distinct from old.origin_type or new.assigned_at is distinct from old.assigned_at) then
    raise exception 'Somente a gestao pode alterar responsavel ou origem.' using errcode = '42501';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
  insert into public.user_roles(id, role) values (new.id, 'visitor') on conflict(id) do nothing;
  insert into public.brokers(id, email, name, active)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'name', new.email), false)
  on conflict(id) do nothing;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.set_user_role(target_email text, new_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare target_id uuid; begin
  if not public.is_privilege_admin() then raise exception 'Apenas administradores podem alterar permissoes.' using errcode = '42501'; end if;
  if new_role not in ('admin','manager','broker','corretor','visitor') then raise exception 'Role invalida'; end if;
  select id into target_id from auth.users where email = target_email;
  if target_id is null then raise exception 'Usuario nao encontrado'; end if;
  update public.user_roles set role = new_role, updated_at = now() where id = target_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_protect_broker_active()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if auth.uid() is not null and not public.is_privilege_admin() and new.active is distinct from old.active then
    raise exception 'Apenas administradores podem ativar ou desativar usuarios.' using errcode = '42501';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_audit_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare fields text[]; before_value jsonb; after_value jsonb; begin
  if tg_op = 'UPDATE' then
    select array_agg(k) into fields from jsonb_object_keys(to_jsonb(new)) k
    where to_jsonb(new)->k is distinct from to_jsonb(old)->k;
    select jsonb_object_agg(k,to_jsonb(old)->k) into before_value from unnest(fields) k
    where k in ('price','status','broker_id','owner_id','publish_on_site','deleted_at','role','disabled_at','due_at');
  end if;
  select jsonb_object_agg(k,to_jsonb(new)->k) into after_value from jsonb_object_keys(to_jsonb(new)) k
  where k in ('price','status','broker_id','owner_id','publish_on_site','deleted_at','role','disabled_at','due_at');
  insert into public.audit_logs(actor_id,entity,entity_id,action,changed_fields,before_data,after_data)
  values(auth.uid(),tg_table_name,new.id::text,tg_op,coalesce(fields,'{}'),before_value,after_value);
  return new;
end $function$
;
