CREATE OR REPLACE FUNCTION public.crm_protect_property_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if auth.uid() is not null and not public.is_privilege_admin() and new.deleted_at is distinct from old.deleted_at then
    raise exception 'Somente administradores podem arquivar imoveis.' using errcode = '42501';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_assign_lead(target_lead bigint, target_broker uuid, assignment_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare previous_broker uuid; lead_name text; begin
  if not public.can_manage_operations() then raise exception 'Acesso negado' using errcode = '42501'; end if;
  if length(trim(coalesce(assignment_reason,''))) not between 1 and 500 then raise exception 'Informe o motivo da atribuicao'; end if;
  if not exists (select 1 from public.brokers b join public.user_roles r on r.id = b.id
    where b.id = target_broker and r.disabled_at is null and r.role in ('admin','manager','broker','corretor')) then
    raise exception 'Corretor invalido ou inativo';
  end if;
  select broker_id, name into previous_broker, lead_name from public.leads where id = target_lead for update;
  if not found then raise exception 'Lead nao encontrado'; end if;
  if previous_broker is not distinct from target_broker then return; end if;
  update public.leads set broker_id = target_broker, assigned_at = now() where id = target_lead;
  insert into public.lead_assignments(lead_id, previous_broker_id, broker_id, assigned_by, reason)
    values(target_lead, previous_broker, target_broker, auth.uid(), trim(assignment_reason));
  insert into public.lead_activities(lead_id,user_id,type,description)
    values(target_lead,auth.uid(),'lead_assigned',trim(assignment_reason));
  insert into public.notifications(user_id,title,description,type)
    values(target_broker,'Novo lead atribuido',lead_name,'lead_atribuido');
  update public.tasks set deleted_at = now(), updated_at = now() where lead_id = target_lead and broker_id = previous_broker and status <> 'concluida';
  insert into public.tasks(title,broker_id,lead_id,due_at)
    values('Primeiro contato: ' || left(coalesce(lead_name, 'Cliente'),120),target_broker,target_lead,now());
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_protect_property_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if auth.uid() is not null and not public.can_manage_operations() and
    (new.owner_id is distinct from old.owner_id or new.broker_id is distinct from old.broker_id) then
    raise exception 'Somente a gestao pode transferir imoveis.' using errcode = '42501';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_protect_role_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if auth.uid() is not null and not public.is_privilege_admin() and
    (new.role is distinct from old.role or new.disabled_at is distinct from old.disabled_at or new.id is distinct from old.id) then
    raise exception 'Somente administradores alteram permissoes.' using errcode = '42501';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_set_property_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare prefix text; label text; candidate text; serial_number text; begin
  if tg_op = 'UPDATE' and old.property_code is not null then
    if new.property_code is distinct from old.property_code then raise exception 'Codigo comercial e permanente'; end if;
    return new;
  end if;
  if new.property_code is not null then raise exception 'Codigo deve ser gerado pelo sistema'; end if;
  label := lower(coalesce(new.type,'') || ' ' || coalesce(new.category,''));
  prefix := case
    when label like '%cobertura%' then 'COB'
    when label like '%studio%' then 'ST'
    when label like '%apart%' then 'AP'
    when label like '%terreno%' or label like '%lote%' then 'TR'
    when label like '%sala%' then 'SA'
    when label like '%loja%' then 'LO'
    when label like '%galp%' then 'GA'
    when label like '%chácara%' or label like '%chacara%' then 'CH'
    when label like '%fazenda%' then 'FA'
    when label like '%comercial%' then 'CO'
    else 'CS' end;
  loop
    serial_number := nextval('public.property_commercial_code_seq')::text;
    candidate := 'PRI-' || prefix || '-' || lpad(serial_number, greatest(6,length(serial_number)), '0');
    exit when not exists(select 1 from public.property_code_registry where code = candidate);
  end loop;
  new.property_code := candidate;
  insert into public.property_code_registry(code,property_id) values(candidate,new.id);
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_prevent_property_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  raise exception 'Arquive o imovel para preservar seu historico.' using errcode = '42501';
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_validate_lead_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
  if new.status = 'perdido' and old.status is distinct from new.status and
    length(trim(coalesce(new.lost_reason,''))) not between 1 and 1000 then
    raise exception 'Informe o motivo da perda.' using errcode = '23514';
  end if;
  if old.first_contact_at is not null and new.first_contact_at is distinct from old.first_contact_at then
    raise exception 'O primeiro contato registrado e permanente.' using errcode = '23514';
  end if;
  if old.first_contact_at is null and new.first_contact_at is not null then new.first_contact_at := now(); end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_lead_timeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
  if tg_op = 'INSERT' then
    insert into public.lead_activities(lead_id,user_id,type,description)
    values(new.id,auth.uid(),'lead_created','Lead recebido');
  else
    if new.status is distinct from old.status then
      insert into public.lead_activities(lead_id,user_id,type,description)
      values(new.id,auth.uid(),'status_changed',coalesce(old.status,'novo') || ' -> ' || new.status);
    end if;
    if old.first_contact_at is null and new.first_contact_at is not null then
      insert into public.lead_activities(lead_id,user_id,type,description)
      values(new.id,auth.uid(),'note','Primeiro contato registrado');
    end if;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_record_contact(target_lead bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare l public.leads; begin
  if not public.can_manage_commercial() then raise exception 'Acesso negado' using errcode = '42501'; end if;
  select * into l from public.leads where id = target_lead for update;
  if not found or (not public.can_manage_operations() and l.broker_id is distinct from auth.uid()) then
    raise exception 'Lead nao encontrado ou sem permissao' using errcode = '42501';
  end if;
  if l.first_contact_at is not null then return; end if;
  update public.leads set first_contact_at = now(), status = case when status = 'novo' then 'em atendimento' else status end where id = target_lead;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_followup_timeline()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
  if new.lead_id is not null then
    insert into public.lead_activities(lead_id,user_id,type,description)
    values(new.lead_id,auth.uid(),'note','Retorno agendado para ' || new.due_at::text);
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_read_notification(target_notification bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ begin
  if not public.can_manage_commercial() then raise exception 'Acesso negado' using errcode = '42501'; end if;
  update public.notifications set read = true where id = target_notification and user_id = auth.uid();
  if not found then raise exception 'Notificacao nao encontrada' using errcode = '42501'; end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_protect_property_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if auth.uid() is not null and not public.can_manage_operations() then
  if tg_op='INSERT' then
   if new.approved_by is not null or new.approved_at is not null then
    raise exception 'Somente a gestao pode aprovar imoveis.' using errcode='42501';
   end if;
   new.workflow_status := 'rascunho';
   new.publish_on_site := false;
   new.submitted_by := auth.uid();
  else
   if new.approved_by is distinct from old.approved_by
      or new.approved_at is distinct from old.approved_at
      or (new.workflow_status is distinct from old.workflow_status
          and new.workflow_status not in ('rascunho','pendente')) then
    raise exception 'Somente a gestao pode aprovar imoveis.' using errcode='42501';
   end if;
   if new.publish_on_site and new.workflow_status not in ('aprovado','publicado') then
    raise exception 'Imovel precisa de aprovacao para publicacao.' using errcode='42501';
   end if;
  end if;
 end if;
 return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.sync_property_media_arrays(target_property_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin

  if auth.uid() is null or not public.can_manage_commercial() or not exists(
    select 1 from public.properties p where p.id=target_property_id and
    (public.can_manage_operations() or p.owner_id=auth.uid() or p.broker_id=auth.uid())) then
    raise exception 'Imovel nao encontrado ou sem permissao.' using errcode='42501';
  end if;

  update public.properties p
  set
    images = coalesce((select array_agg(pi.url order by pi.sort_order, pi.id) from public.property_images pi where pi.property_id = target_property_id), '{}'::text[]),
    videos = coalesce((select array_agg(pv.url order by pv.sort_order, pv.id) from public.property_videos pv where pv.property_id = target_property_id), '{}'::text[]),
    main_image_url = coalesce((select pi.url from public.property_images pi where pi.property_id = target_property_id order by pi.is_main desc, pi.sort_order, pi.id limit 1), p.main_image_url),
    video_url = coalesce((select pv.url from public.property_videos pv where pv.property_id = target_property_id order by pv.sort_order, pv.id limit 1), p.video_url)
  where p.id = target_property_id;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.crm_validate_private_media_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare object_path text;
begin
if position('/api/property-media/' in new.url)>0 then
object_path:=split_part(new.url,'/api/property-media/',2);
if object_path !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$' or not public.can_manage_commercial()
or (not public.can_manage_operations() and split_part(object_path,'/',1)<>auth.uid()::text
and not exists(select 1 from public.property_images i where i.property_id=new.property_id and i.url=new.url))
or not exists(select 1 from storage.objects where bucket_id='crm-property-images' and name=object_path) then
raise exception 'Midia privada inexistente ou sem permissao.' using errcode='42501';
end if;
end if;
return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.crm_public_presentation(target_token uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select jsonb_build_object('title',s.title,'message',s.message,'expires_at',s.expires_at,'broker',(select jsonb_build_object('name',b.name,'phone',b.phone,'creci',b.creci) from public.brokers b where b.id=s.owner_id and b.active),'properties',(select jsonb_agg(jsonb_build_object('id',p.id,'title',p.title,'property_code',p.property_code,'slug',p.slug,'description',p.description,'location',p.location,'price',p.price,'bedrooms',p.bedrooms,'bathrooms',p.bathrooms,'garage',p.garage,'area',p.area,'images',p.images,'videos',p.videos,'status',p.status)) from public.properties p where p.id=any(s.property_ids)),'assets',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'category',a.category,'mime_type',v.mime_type,'size_bytes',v.size_bytes,'path',v.storage_path)) from public.marketing_assets a join public.asset_versions v on v.id=a.current_version_id where a.id=any(s.asset_ids) and crm_private.public_asset(v.storage_path) and exists(select 1 from public.asset_relations r where r.asset_id=a.id and(r.property_id=any(s.property_ids) or exists(select 1 from public.development_units u where u.development_id=r.development_id and u.property_id=any(s.property_ids))))),'[]'::jsonb)) from public.marketing_shares s where s.id=crm_private.valid_share(target_token) $function$
;
CREATE OR REPLACE FUNCTION public.crm_save_property_media(target_property_id bigint, image_urls text[], video_urls text[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if not public.can_manage_commercial() or not exists(
  select 1 from public.properties p where p.id=target_property_id and
  (public.can_manage_operations() or p.owner_id=auth.uid() or p.broker_id=auth.uid())) then
  raise exception 'Imovel nao encontrado ou sem permissao.' using errcode='42501';
 end if;
 if coalesce(cardinality(image_urls),0)>50 or coalesce(cardinality(video_urls),0)>20
 or exists(select 1 from unnest(coalesce(image_urls,'{}') || coalesce(video_urls,'{}')) u
   where u is null or u !~ '^https?://[^[:space:]]+$') then
  raise exception 'Midias invalidas.' using errcode='23514';
 end if;
 perform 1 from public.properties where id=target_property_id for update;
 delete from public.property_images where property_id=target_property_id and not (url=any(coalesce(image_urls,'{}')));
 update public.property_images i set sort_order=x.n-1,is_main=x.n=1
 from unnest(image_urls) with ordinality as x(u,n) where i.property_id=target_property_id and i.url=x.u;
 insert into public.property_images(property_id,url,sort_order,is_main)
 select target_property_id,u,n-1,n=1 from unnest(image_urls) with ordinality as x(u,n)
 where not exists(select 1 from public.property_images i where i.property_id=target_property_id and i.url=x.u);
 delete from public.property_videos where property_id=target_property_id;
 insert into public.property_videos(property_id,url,sort_order)
 select target_property_id,u,n-1 from unnest(video_urls) with ordinality as x(u,n);
 perform public.sync_property_media_arrays(target_property_id);
end $function$
;
CREATE OR REPLACE FUNCTION crm_private.guard_asset()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ begin
if tg_op='UPDATE' then
 if new.owner_id<>old.owner_id or new.scope<>old.scope then raise exception using errcode='42501',message='Proprietário e escopo são permanentes.'; end if;
 if (new.status is distinct from old.status and new.status='aprovado') or(new.visibility is distinct from old.visibility and new.visibility='public') then if not public.can_manage_operations() then raise exception using errcode='42501',message='A gestão deve aprovar a divulgação.'; end if; end if;
 -- Changing the file of approved material always requires reapproval, including manager uploads.
 if new.current_version_id is distinct from old.current_version_id then new.status:='pendente'; end if;
else if (new.status='aprovado' or new.visibility='public') and not public.can_manage_operations() then raise exception using errcode='42501',message='A gestão deve aprovar a divulgação.'; end if;
end if;
if new.current_version_id is not null and not exists(select 1 from public.asset_versions v where v.id=new.current_version_id and v.asset_id=new.id) then raise exception using errcode='23514',message='Versão inválida.'; end if;
new.updated_at:=now();return new;end $function$
;
CREATE OR REPLACE FUNCTION crm_private.valid_share(target_token uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
select s.id from public.marketing_shares s where s.token=target_token and s.revoked_at is null and s.expires_at>now() and not exists(select 1 from unnest(s.property_ids) pid where not exists(select 1 from public.properties p where p.id=pid and p.deleted_at is null and p.publish_on_site and p.presentation_enabled and p.workflow_status in ('aprovado','publicado') and p.status in ('ativo','reservado','vendido','alugado'))) $function$
;
CREATE OR REPLACE FUNCTION public.crm_confirm_presentation_share(target_share bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.marketing_shares; inserted_id bigint;
begin
 if not public.can_manage_commercial() then raise exception using errcode='42501',message='Sessão comercial necessária.';end if;
 select * into s from public.marketing_shares where id=target_share and(owner_id=auth.uid() or public.can_manage_operations());
 if s.id is null then raise exception using errcode='42501',message='Apresentação não autorizada.';end if;
 if s.lead_id is not null and not exists(select 1 from public.leads l where l.id=s.lead_id and(l.broker_id=auth.uid() or public.can_manage_operations())) then raise exception using errcode='42501',message='Lead não autorizado.';end if;
 insert into public.crm_event_log(owner_id,event_type,entity_id,idempotency_key) values(auth.uid(),'presentation_shared',s.id,'share-confirmed:'||s.id) on conflict(idempotency_key) do nothing returning id into inserted_id;
 if inserted_id is not null and s.lead_id is not null then insert into public.lead_activities(lead_id,user_id,type,description) values(s.lead_id,auth.uid(),'note','Envio confirmado pelo corretor: '||s.title||' · canal '||s.channel||' · link /apresentacoes/'||s.token::text);end if;
 return true;
end $function$
;
create view public."admin_dashboard_metrics" with(security_invoker=true) as  SELECT ( SELECT count(*) AS count
           FROM properties) AS total_properties,
    ( SELECT count(*) AS count
           FROM properties
          WHERE (properties.status = 'ativo'::text)) AS active_properties,
    ( SELECT count(*) AS count
           FROM properties
          WHERE (properties.status = 'vendido'::text)) AS sold_properties,
    ( SELECT count(*) AS count
           FROM leads) AS total_leads,
    ( SELECT count(*) AS count
           FROM leads
          WHERE (leads.status = 'novo'::text)) AS new_leads,
    ( SELECT count(*) AS count
           FROM property_views) AS total_views;;
create view public."property_metrics" with(security_invoker=true) as  SELECT p.id,
    p.title,
    p.slug,
    p.category,
    p.status,
    count(DISTINCT v.id) AS views_count,
    count(DISTINCT f.id) AS favorites_count,
    count(DISTINCT l.id) AS leads_count
   FROM (((properties p
     LEFT JOIN property_views v ON ((v.property_id = p.id)))
     LEFT JOIN property_favorites f ON ((f.property_id = p.id)))
     LEFT JOIN leads l ON ((l.property_id = p.id)))
  GROUP BY p.id, p.title, p.slug, p.category, p.status;;
create view public."property_admin_metrics" with(security_invoker=true) as  SELECT p.id,
    p.title,
    p.slug,
    p.status,
    p.featured,
    GREATEST(COALESCE(p.view_count, 0), (count(DISTINCT pv.id))::integer) AS views_count,
    (count(DISTINCT pf.id))::integer AS favorites_count,
    (count(DISTINCT l.id))::integer AS leads_count
   FROM (((properties p
     LEFT JOIN property_views pv ON ((pv.property_id = p.id)))
     LEFT JOIN property_favorites pf ON ((pf.property_id = p.id)))
     LEFT JOIN leads l ON ((l.property_id = p.id)))
  GROUP BY p.id, p.title, p.slug, p.status, p.featured, p.view_count;;
create view public."lead_origin_metrics" with(security_invoker=true) as  SELECT COALESCE(source, 'site'::text) AS source,
    count(*) AS total,
    count(*) FILTER (WHERE (status = 'novo'::text)) AS novos,
    count(*) FILTER (WHERE (status = 'convertido'::text)) AS convertidos
   FROM leads
  GROUP BY COALESCE(source, 'site'::text);;
