create policy "CRM contact relationships" on public."crm_contact_links" as PERMISSIVE for ALL to "authenticated" using ((can_manage_commercial() AND (EXISTS ( SELECT 1
   FROM clients c
  WHERE ((c.id = crm_contact_links.contact_id) AND (c.deleted_at IS NULL)))) AND (((lead_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM leads l
  WHERE (l.id = crm_contact_links.lead_id)))) OR ((property_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM properties p
  WHERE ((p.id = crm_contact_links.property_id) AND (can_manage_operations() OR (p.owner_id = auth.uid()) OR (p.broker_id = auth.uid()))))))))) with check ((can_manage_commercial() AND (EXISTS ( SELECT 1
   FROM clients c
  WHERE ((c.id = crm_contact_links.contact_id) AND (c.deleted_at IS NULL)))) AND (((lead_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM leads l
  WHERE (l.id = crm_contact_links.lead_id)))) OR ((property_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM properties p
  WHERE ((p.id = crm_contact_links.property_id) AND (can_manage_operations() OR (p.owner_id = auth.uid()) OR (p.broker_id = auth.uid())))))))));
create policy "CRM private media read" on storage."objects" as PERMISSIVE for SELECT to "anon","authenticated" using (((bucket_id = 'crm-property-images'::text) AND ((can_manage_commercial() AND (can_manage_operations() OR ((storage.foldername(name))[1] = (auth.uid())::text))) OR (EXISTS ( SELECT 1
   FROM (property_images i
     JOIN properties p ON ((p.id = i.property_id)))
  WHERE (("right"(i.url, length(('/api/property-media/'::text || objects.name))) = ('/api/property-media/'::text || objects.name)) AND ((p.publish_on_site AND (p.deleted_at IS NULL) AND (p.workflow_status = ANY (ARRAY['aprovado'::text, 'publicado'::text])) AND (p.status = ANY (ARRAY['ativo'::text, 'reservado'::text, 'vendido'::text, 'alugado'::text]))) OR (can_manage_commercial() AND (can_manage_operations() OR (p.owner_id = auth.uid()) OR (p.broker_id = auth.uid()))))))))));
create policy "CRM private media upload" on storage."objects" as PERMISSIVE for INSERT to "authenticated" with check (((bucket_id = 'crm-property-images'::text) AND can_manage_commercial() AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.webp$'::text)));
create policy "marketing_storage_public" on storage."objects" as PERMISSIVE for SELECT to "anon" using (((bucket_id = 'crm-marketing'::text) AND storage.allow_any_operation(ARRAY['object.get_authenticated_info'::text, 'object.get_authenticated'::text]) AND crm_private.public_asset(name)));
create policy "marketing_storage_read" on storage."objects" as PERMISSIVE for SELECT to "authenticated" using (((bucket_id = 'crm-marketing'::text) AND (can_manage_commercial() AND ((split_part(name, '/'::text, 1) = (auth.uid())::text) OR can_manage_operations() OR (EXISTS ( SELECT 1
   FROM (asset_versions v
